it.each([
			[true, false],
			[false, true],
		] as const)(
			"keeps metadata and its physical index aligned when indexed changes from %s to %s during concurrent updates",
			async (indexed, nextIndexed) => {
				const field = await registry.createField("posts", {
					slug: "priority",
					label: "Priority",
